WITH totals AS (SELECT r.id_user,ceil(sum(r.points)::numeric/(SELECT count(*) FROM public.zsl_level WHERE id_round=$1))::integer AS points FROM public.zsl_level_result r JOIN public.zsl_level l ON l.id=r.id_level WHERE l.id_round=$1 GROUP BY r.id_user), ranked AS(SELECT *,rank() OVER(ORDER BY points DESC)::integer AS position FROM totals) INSERT INTO public.zsl_round_result(id_round,id_user,points,position,date_created) SELECT $1,id_user,points,position,clock_timestamp() FROM ranked ON CONFLICT(id_round,id_user) DO UPDATE SET points=excluded.points,position=excluded.position,date_updated=clock_timestamp()
